def crop_models(season: str | None = None, category: str | None = None) -> list[CropRecommendation]:
    items = CROPS
    if season:
        items = [item for item in items if item["season"] == season]
    if category and category != "any":
        items = [item for item in items if item["category"] == category]
    return [CropRecommendation.model_validate(item) for item in items]
